/*
 * A163619  Let q(p) be the smallest prime greater than the prime p. A
 *          positive integer n is included in this sequence if n+1 is
 *          divisible by q(p) for each prime p dividing n.
 * https://oeis.org/A163619
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th positive integer m such that for every prime p
 *            dividing m, its successor prime q(p) divides m+1. (The sequence
 *            is generated by brute‑force search.)
 * Range:     u8 n <= 9, u16 n <= 29, u32 n <= 40, u64 n <= 40, u128 n <= 40,
 *            big any n
 * Helpers:   factor_u64, isPrimeTrial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/factor_u64.h"
#include "../utils/isPrimeTrial.h"

static seq_t *cache = NULL;          /* cached terms */
static size_t cacheSize = 0;         /* number of cached terms */
static size_t cacheCap  = 0;         /* allocated capacity */
static uint64_t lastTested = 1;      /* last integer tested */

/* Find the smallest prime greater than (or equal to) start  */
static seq_t next_prime_of_uint64(uint64_t start)
{
    for (;;) {
        if (isPrimeTrial((seq_t)start))
            return (seq_t)start;
        if (start == (uint64_t)-1)   /* should never happen */
            return 0;
        ++start;
    }
}

/* Fill the cache up to index n (≥1) */
static void ensure_terms(idx_t n)
{
    if (cacheSize >= (size_t)n)
        return;

    /* grow cache if necessary */
    if (cacheCap < (size_t)n) {
        size_t newCap = cacheCap ? cacheCap * 2 : 64;
        if (newCap < (size_t)n) newCap = (size_t)n;
        seq_t *tmp = (seq_t *)realloc(cache, newCap * sizeof(seq_t));
        if (!tmp) abort();
        cache = tmp;
        cacheCap = newCap;
    }

    while (cacheSize < (size_t)n) {
        ++lastTested;
        uint64_t m = lastTested;

        /* factor m to obtain distinct prime factors */
        size_t cnt = 0;
        uint64_t pr[64], ex[64];   /* enough for all 64‑bit values */
        factor_u64(m, pr, ex, &cnt);

        /* test condition for each prime factor */
        bool ok = true;
        for (size_t i = 0; i < cnt && ok; ++i) {
            seq_t q = next_prime_of_uint64(pr[i] + 1); /* q(p) */
            seq_t val = (seq_t)(m + 1);
            if (val % q != 0)
                ok = false;
        }

        if (ok) {
            cache[cacheSize++] = (seq_t)m;
        }
    }
}

seq_t a(idx_t n)
{
    if (n < 1)
        return (seq_t)0;           /* undefined for n<1, safe default */
    ensure_terms(n);
    return cache[n - 1];           /* offset 1: a(1) is the first term */
}
